1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
34	  sword: 100,
35	  amulet: 60,
36	  staff: 80,
37	  potion: 40,
38	  rune: 25,
39	  moonstone: 25,
40	};
41	
42	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
43	
44	const BLOCK_SIZE = 3;
45	const BLOCK_BASE_PREMIUM = 60;
46	
47	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
48	  alikeItems.length === BLOCK_SIZE;
49	
50	const sumOfBasePremiums = (items: Item[]): number =>
51	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
52	
53	const CURSE_SURCHARGE_RATE = 0.5;
54	const HIGH_ENCHANTMENT_LEVEL = 5;
55	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
56	
57	const isCursed = (item: Item): boolean => item.cursed === true;
58	
59	const isHighlyEnchanted = (item: Item): boolean =>
60	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
61	
62	// A rate table prices one subject: every row whose risk applies contributes its
63	// rate, and the total is their sum. Both the item surcharges and the policy-wide
64	// modifiers are rate tables — they differ only in what they are applied to.
65	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
66	
67	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
68	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
69	
70	// Every item-specific surcharge is a rate on THAT item's base premium, charged
71	// when its risk applies. Adding a new one means adding a row here — nothing else.
72	const ITEM_SURCHARGES: RateTable<Item> = [
73	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
74	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
75	];
76	
77	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
78	
79	const itemSurchargesOn = (items: Item[]): number =>
80	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
81	
82	// Items of the same type are "alike"; each group is priced together so a
83	// building block can be recognised.
84	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
85	  ...items
86	    .reduce(
87	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
88	      new Map<string, Item[]>(),
89	    )
90	    .values(),
91	];
92	
93	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
94	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
95	
96	const policyBaseOf = (items: Item[]): number =>
97	  alikeItemGroupsIn(items).reduce(
98	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
99	    0,
100	  );
101	
102	// Rounding always favours the MHPCO: premiums up, payouts down.
103	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
104	
105	const LOYALTY_YEARS = 2;
106	const LOYALTY_DISCOUNT_RATE = -0.2;
107	
108	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
109	
110	// Each item in a quote is treated as a first insurance regardless of customer
111	// history, so this surcharge is unconditional.
112	const appliesUnconditionally = (): boolean => true;
113	
114	const isLongStanding = ({ customer }: QuoteContext): boolean =>
115	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
116	
117	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
118	  precedingQuotes > 0;
119	
120	// A quote is priced from the customer plus its place in the scenario's history.
121	type QuoteContext = { customer: Customer; precedingQuotes: number };
122	
123	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
124	// base that already includes the item surcharges. Surcharges carry a positive
125	// rate, discounts a negative one. Adding a new one means adding a row here.
126	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
127	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
128	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
129	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
130	];
131	
132	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
133	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
134	
135	const quoteFor = (items: Item[], context: QuoteContext): Result => {
136	  const policyBase = policyBaseOf(items);
137	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
138	  return {
139	    premium: premiumRoundedInMHPCOsFavour(
140	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
141	    ),
142	  };
143	};
144	
145	const DEDUCTIBLE_PER_DAMAGE = 100;
146	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
147	
148	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
149	  sword: 1000,
150	  amulet: 600,
151	  staff: 800,
152	  potion: 400,
153	  rune: 250,
154	  moonstone: 250,
155	};
156	
157	const insuranceSumOf = (items: Item[]): number =>
158	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
159	
160	// A policy created by a quote step, tracked by that step's index so later claims
161	// can find it and draw down its cap.
162	type Policy = { items: Item[]; remainingCap: number };
163	
164	const policyFor = (items: Item[]): Policy => ({
165	  items,
166	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
167	});
168	
169	const payoutForDamage = (damage: Damage): number =>
170	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
171	
172	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
173	  const payout = incident.damages.reduce(
174	    (sum, damage) => sum + payoutForDamage(damage),
175	    0,
176	  );
177	  const remainingCap = policy.remainingCap - payout;
178	  return [{ payout, remainingCap }, { ...policy, remainingCap }];
179	};
180	
181	// What the scenario has accumulated before the current step: the results so far,
182	// the history a quote is priced against, and the policies earlier quotes created.
183	type ScenarioState = {
184	  results: Result[];
185	  precedingQuotes: number;
186	  policies: Record<number, Policy>;
187	};
188	
189	const INITIAL_SCENARIO_STATE: ScenarioState = {
190	  results: [],
191	  precedingQuotes: 0,
192	  policies: {},
193	};
194	
195	const afterQuote = (
196	  state: ScenarioState,
197	  items: Item[],
198	  customer: Customer,
199	  stepIndex: number,
200	): ScenarioState => ({
201	  results: [
202	    ...state.results,
203	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
204	  ],
205	  precedingQuotes: state.precedingQuotes + 1,
206	  policies: { ...state.policies, [stepIndex]: policyFor(items) },
207	});
208	
209	const afterClaim = (
210	  state: ScenarioState,
211	  policyIndex: number,
212	  incident: Incident,
213	): ScenarioState => {
214	  const [result, policy] = claimFor(incident, state.policies[policyIndex]);
215	  return {
216	    ...state,
217	    results: [...state.results, result],
218	    policies: { ...state.policies, [policyIndex]: policy },
219	  };
220	};
221	
222	const afterStep = (
223	  state: ScenarioState,
224	  step: Step,
225	  customer: Customer,
226	  stepIndex: number,
227	): ScenarioState =>
228	  step.op === "quote"
229	    ? afterQuote(state, step.items, customer, stepIndex)
230	    : afterClaim(state, step.policy, step.incident);
231	
232	export const runScenario = (scenario: Scenario): { results: Result[] } => {
233	  const { results } = scenario.steps.reduce(
234	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
235	    INITIAL_SCENARIO_STATE,
236	  );
237	  return { results };
238	};
